begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values('ab000000-0000-4000-8000-000000000001','anesthesia-staff@example.test','{"first_name":"Anesthesia","last_name":"Staff"}'),('ab000000-0000-4000-8000-000000000002','anesthesia-inactive@example.test','{"first_name":"Inactive","last_name":"Staff"}');
update public.profiles set is_active = true where id in ('ab000000-0000-4000-8000-000000000001','ab000000-0000-4000-8000-000000000002');
insert into public.user_roles (user_id, role) values ('ab000000-0000-4000-8000-000000000001','STAFF'),('ab000000-0000-4000-8000-000000000002','STAFF');

update public.profiles set is_active=false where id='ab000000-0000-4000-8000-000000000002';
create temp table anesthesia_fixture(kind text primary key,id uuid);grant all on anesthesia_fixture to authenticated;
select ok(not has_table_privilege('authenticated','public.patient_anesthesia_records','UPDATE'),'Direct draft/signature updates denied');
select ok(not has_table_privilege('service_role','public.patient_anesthesia_records','DELETE'),'Service cannot delete native anesthesia records');
select ok(not has_table_privilege('authenticated','public.anesthesia_record_revisions','UPDATE'),'History immutable');
select ok(not has_table_privilege('anon','public.patient_anesthesia_records','SELECT'),'Anonymous access denied');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ab000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into anesthesia_fixture select 'client',id from public.save_client(auth.uid(),null,null,'Synthetic','Anesthesia',null,null,'EMAIL',null,null);
insert into anesthesia_fixture select 'pet',id from public.save_patient(null,(select id from anesthesia_fixture where kind='client'),null,'One','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
insert into anesthesia_fixture select 'other',id from public.save_patient(null,(select id from anesthesia_fixture where kind='client'),null,'Two','Cat',null,null,'unknown',null,'unknown','unknown',null,null,null);
create function pg_temp.a_save(p_id uuid,p_version integer,p_extra jsonb default '{}') returns public.patient_anesthesia_records language sql as $$select public.save_patient_anesthesia_record(p_id,(select id from anesthesia_fixture where kind='pet'),p_version,'{"procedure_name":"Synthetic procedure","started_at":"2026-01-01T16:00:00Z","team":"Synthetic clinician and technician","source":"manual","assessment":"Documented assessment","plan":"Documented plan"}'::jsonb||p_extra)$$;
select lives_ok($$select pg_temp.a_save('ab100000-0000-4000-8000-000000000001',null)$$,'Create authored anesthesia draft');
select lives_ok($$select pg_temp.a_save('ab100000-0000-4000-8000-000000000001',null)$$,'Lost response retry idempotent');
select is((select count(*) from public.anesthesia_record_revisions),1::bigint,'No duplicate version on retry');
select is((select observations from public.patient_anesthesia_records where id='ab100000-0000-4000-8000-000000000001'),'[]'::jsonb,'No assumed normal values');
select throws_ok($$select pg_temp.a_save('ab100000-0000-4000-8000-000000000001',0,'{"plan":"Conflicting edit"}')$$,'40001',null,'Stale draft rejected');
select throws_ok($$select public.save_patient_anesthesia_record('ab100000-0000-4000-8000-000000000001',(select id from anesthesia_fixture where kind='other'),1,'{}')$$,'42501',null,'Cross-patient draft rejected');
select throws_ok($$select public.sign_patient_anesthesia_record('ab100000-0000-4000-8000-000000000001',(select id from anesthesia_fixture where kind='other'),1)$$,'42501',null,'Cross-patient signature rejected');
select throws_ok($$select public.sign_patient_anesthesia_record('ab100000-0000-4000-8000-000000000001',(select id from anesthesia_fixture where kind='pet'),1)$$,'23514',null,'End time required before signature');
select throws_ok($$select pg_temp.a_save(gen_random_uuid(),null,'{"started_at":"infinity"}')$$,'23514',null,'Infinite start rejected');
select throws_ok($$select pg_temp.a_save(gen_random_uuid(),null,'{"started_at":"2999-01-01T00:00:00Z"}')$$,'23514',null,'Future procedure rejected');
select throws_ok($$select pg_temp.a_save(gen_random_uuid(),null,'{"ended_at":"2025-01-01T00:00:00Z"}')$$,'23514',null,'End before start rejected');
select throws_ok($$select pg_temp.a_save(gen_random_uuid(),null,'{"observations":[{"at":"2026-01-01T16:01:00Z","label":"Parameter","value":90,"unit":"","notes":""}]}')$$,'23514',null,'Explicit observation units required');
select throws_ok($$select pg_temp.a_save(gen_random_uuid(),null,'{"observations":[{"at":"2026-01-01T16:01:00Z","label":"Parameter","value":"NaN","unit":"bpm","notes":""}]}')$$,'23514',null,'Nonfinite monitoring rejected');
select throws_ok($$select pg_temp.a_save(gen_random_uuid(),null,'{"observations":[{"at":"2026-01-01T15:59:00Z","label":"Parameter","value":90,"unit":"bpm","notes":""}]}')$$,'23514',null,'Observation before start rejected');
select throws_ok($$select pg_temp.a_save(gen_random_uuid(),null,'{"ended_at":"2026-01-01T16:30:00Z","events":[{"at":"2026-01-01T16:31:00Z","kind":"medication","description":"Documented amount and units"}]}')$$,'23514',null,'Event after procedure end rejected');
select throws_ok($$select pg_temp.a_save(gen_random_uuid(),null,'{"source":"transcribed_from_document"}')$$,'23514',null,'Transcription requires actual source attachment and description');
select throws_ok($$select pg_temp.a_save(gen_random_uuid(),null,'{"updated_by":"ab000000-0000-4000-8000-000000000002"}')$$,'23514',null,'Payload actor tampering rejected');
reset role;
insert into public.patient_documents(id,pet_id,file_name,file_path,mime_type,file_size,category,source,visibility,status,created_by) values('ab300000-0000-4000-8000-000000000001',(select id from anesthesia_fixture where kind='other'),'other.pdf','anesthesia-synthetic/other.pdf','application/pdf',10,'anesthesia','synthetic','internal','ready','ab000000-0000-4000-8000-000000000001'),('ab300000-0000-4000-8000-000000000002',(select id from anesthesia_fixture where kind='pet'),'pending.pdf','anesthesia-synthetic/pending.pdf','application/pdf',10,'anesthesia','synthetic','internal','uploading','ab000000-0000-4000-8000-000000000001');
set local role authenticated;
select throws_ok($$select pg_temp.a_save(gen_random_uuid(),null,'{"original_document_id":"ab300000-0000-4000-8000-000000000001"}')$$,'42501',null,'Other patient original file rejected');
select throws_ok($$select pg_temp.a_save(gen_random_uuid(),null,'{"original_document_id":"ab300000-0000-4000-8000-000000000002"}')$$,'42501',null,'Pending original file rejected');
select lives_ok($$select pg_temp.a_save('ab100000-0000-4000-8000-000000000001',1,'{"ended_at":"2026-01-01T16:30:00Z","observations":[{"at":"2026-01-01T16:01:00Z","label":"Observed parameter","value":0,"unit":"mmHg","notes":"Source observation"}],"events":[{"at":"2026-01-01T16:03:00Z","kind":"procedure","description":"Documented event"}]}')$$,'Save explicit monitoring and documentary event');
select is((select count(*) from public.anesthesia_record_revisions),2::bigint,'Revisions preserve original draft');
select throws_ok($$select public.sign_patient_anesthesia_record('ab100000-0000-4000-8000-000000000001',(select id from anesthesia_fixture where kind='pet'),1)$$,'40001',null,'Stale signature rejected');
select lives_ok($$select public.sign_patient_anesthesia_record('ab100000-0000-4000-8000-000000000001',(select id from anesthesia_fixture where kind='pet'),2)$$,'Reviewed saved record signed');
select lives_ok($$select public.sign_patient_anesthesia_record('ab100000-0000-4000-8000-000000000001',(select id from anesthesia_fixture where kind='pet'),2)$$,'Lost signature response retry idempotent');
select is((select count(*) from public.anesthesia_record_revisions),3::bigint,'Signature retry adds no second version');
select throws_ok($$select pg_temp.a_save('ab100000-0000-4000-8000-000000000001',3,'{"assessment":"Overwrite"}')$$,'23514',null,'Signed record cannot be overwritten');
select throws_ok($$select public.add_anesthesia_record_addendum(gen_random_uuid(),'ab100000-0000-4000-8000-000000000001',(select id from anesthesia_fixture where kind='other'),'Mismatch')$$,'42501',null,'Cross patient addendum rejected');
select lives_ok($$select public.add_anesthesia_record_addendum('ab200000-0000-4000-8000-000000000001','ab100000-0000-4000-8000-000000000001',(select id from anesthesia_fixture where kind='pet'),'Reviewed source clarification')$$,'Append authored correction');
select lives_ok($$select public.add_anesthesia_record_addendum('ab200000-0000-4000-8000-000000000001','ab100000-0000-4000-8000-000000000001',(select id from anesthesia_fixture where kind='pet'),'Reviewed source clarification')$$,'Addendum retry idempotent');
select is((select count(*) from public.anesthesia_record_addenda),1::bigint,'No duplicate correction');
select throws_ok($$select public.add_anesthesia_record_addendum('ab200000-0000-4000-8000-000000000001','ab100000-0000-4000-8000-000000000001',(select id from anesthesia_fixture where kind='pet'),'Changed replay')$$,'42501',null,'Changed addendum retry rejected');
select is((select signed_by from public.patient_anesthesia_records where id='ab100000-0000-4000-8000-000000000001'),auth.uid(),'Authenticated actor owns signature');
select set_config('request.jwt.claims','{"sub":"ab000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is((select count(*) from public.patient_anesthesia_records),0::bigint,'Inactive staff cannot read records');
select throws_ok($$select pg_temp.a_save(gen_random_uuid(),null)$$,'42501',null,'Inactive actor cannot save');
select * from finish();rollback;
